//! Native symbol extraction, ported per language from WrongStack's parsers.
//! Each port is validated against known answers generated by the original
//! TypeScript implementation (`contracts/fixtures/parser-kat.json`).

pub mod json;
pub mod yaml;

use serde::Serialize;

use crate::js::{self, U16};

/// A parsed symbol before it is written (the parser's `Symbol` shape).
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ParsedSymbol {
    pub kind: &'static str,
    pub name: String,
    pub line: usize,
    /// UTF-16 code units from the start of the line.
    pub col: usize,
    pub signature: String,
    pub doc_comment: String,
    pub scope: String,
    pub text: String,
}

impl ParsedSymbol {
    /// `makeSymbol` in the JSON/YAML parsers: `text = "${name} ${signature}".trim()`.
    pub fn simple(
        kind: &'static str,
        name: &U16,
        line: usize,
        col: usize,
        signature: &U16,
    ) -> Self {
        let mut text = name.to_vec();
        text.push(0x20);
        text.extend_from_slice(signature);
        Self {
            kind,
            name: js::string(name),
            line,
            col,
            signature: js::string(signature),
            doc_comment: String::new(),
            scope: String::new(),
            text: js::string(js::trim(&text)),
        }
    }
}

/// Parser output for one file.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize)]
pub struct Parsed {
    pub symbols: Vec<ParsedSymbol>,
    /// Set when the TypeScript parser would also have produced references
    /// that this port does not implement yet; such a file must not be
    /// written natively.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub unsupported: Option<String>,
}
